sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    if (newValue === '') {
        g_form.clearValue('duration');
		return;
    }

	//Use this to convert from user to system format
	//If your instance use system format only, just ignore it
	var start_date = g_form.getValue('start_time');
	var end_date = g_form.getValue('end_time');

	g_form.addInfoMessage('Start: ' + start_date + ', End: ' + end_date);

    var ga = new GlideAjax('CalculateDate');
    ga.addParam('sysparm_name', 'calculateDatediff');
    ga.addParam('sysparm_start_date', start_date);
    ga.addParam('sysparm_end_date', end_date);
    ga.getXMLAnswer(function(response) {
		g_form.addInfoMessage('answer: ' + response);
		g_form.setValue('duration', response);
    });

}
